update user_voc_bound_statistics
set free= free + #{reward},
total = total + #{reward},
available = available + #{reward}
where user_id=#{userId}

update user_voc_bound_statistics
set pay= pay + #{amount},
total = total + #{amount},
available = available + #{amount}
where user_id=#{userId}

update user_voc_bound_statistics
set exchange= exchange + #{amount},
available = available - #{amount},
occupied = occupied + #{amount}
where user_id=#{userId}

update user_voc_bound_statistics
set occupied = occupied + #{occupied},
available = available - #{occupied}
where user_id=#{userId}
